import{_ as t,o as a,c as r,aQ as o}from"./chunks/framework.C8WmN7-d.js";const g=JSON.parse('{"title":"Fast Note Sync","description":"","frontmatter":{},"headers":[],"relativePath":"others/obsidian/fast-note-sync/index.md","filePath":"others/obsidian/fast-note-sync/index.md"}'),s={name:"others/obsidian/fast-note-sync/index.md"};function n(i,e,l,c,h,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="fast-note-sync" tabindex="-1">Fast Note Sync <a class="header-anchor" href="#fast-note-sync" aria-label="Permalink to &quot;Fast Note Sync&quot;">​</a></h1><p><a href="https://github.com/haierkeys/obsidian-fast-note-sync" target="_blank" rel="noreferrer">Fast Note Sync</a> 是 Obsidian 的多端实时同步插件，需配合自托管后端 <a href="https://github.com/haierkeys/fast-note-sync-service" target="_blank" rel="noreferrer">Fast Note Sync Service</a> 使用，支持笔记、附件与配置的跨设备同步。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>插件本身只负责客户端同步，需先部署 <strong>Fast Note Sync Service</strong> 服务端：</p><ol><li>使用 Docker 等方式部署后端（可参考 <a href="https://github.com/haierkeys/fast-note-sync-service" target="_blank" rel="noreferrer">fast-note-sync-service</a> 或 <a href="https://zeabur.com/zh-CN/templates/CSBIG1" target="_blank" rel="noreferrer">Zeabur 模板</a>）。</li><li>浏览器访问服务端 Web 管理面板（如 <code>http://localhost:9000</code> 或部署后的域名）。</li><li>注册账号，在「Note Vaults」中创建笔记库，并获取<strong>远端服务配置</strong>字符串。</li></ol><h2 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to &quot;安装插件&quot;">​</a></h2><p>任选一种方式：</p><ul><li><strong>BRAT（推荐，支持手机）</strong>：在社区插件中安装 <a href="https://github.com/TfTHacker/obsidian42-brat" target="_blank" rel="noreferrer">BRAT</a>，在 BRAT 设置里 <strong>Add plugin</strong>，粘贴 <code>https://github.com/haierkeys/obsidian-fast-note-sync</code>。</li><li><strong>手动安装</strong>：从 <a href="https://github.com/haierkeys/obsidian-fast-note-sync/releases" target="_blank" rel="noreferrer">Releases</a> 下载，解压到仓库的 <code>.obsidian/plugins/</code> 目录。</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>插件尚未上架 Obsidian 官方社区商店，需通过 BRAT 或手动安装。</p></div><h2 id="使用步骤" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h2><h3 id="_1-连接服务端" tabindex="-1">1. 连接服务端 <a class="header-anchor" href="#_1-连接服务端" aria-label="Permalink to &quot;1. 连接服务端&quot;">​</a></h3><p><strong>方式 A：一键授权（桌面端）</strong></p><ol><li>在服务端 Web 面板左侧选择 <strong>Note Vaults</strong>。</li><li>点击 <strong>「一键授权 Obsidian」</strong>，系统会唤起 Obsidian 并完成授权信息传递。</li></ol><p><strong>方式 B：粘贴远端配置</strong></p><ol><li>在服务端复制<strong>远端服务配置</strong>字符串。</li><li>打开 Obsidian → 设置 → <strong>Fast Note Sync</strong> → 点击 <strong>「粘贴远端配置」</strong>，将配置粘贴到输入框并保存。</li></ol><h3 id="_2-开始同步" tabindex="-1">2. 开始同步 <a class="header-anchor" href="#_2-开始同步" aria-label="Permalink to &quot;2. 开始同步&quot;">​</a></h3><ol><li>在 Obsidian 设置中<strong>启用</strong> Fast Note Sync 插件。</li><li>确认插件设置中监听已开启（<code>isWatchEnabled</code> 为 true）。</li><li>新建或修改笔记，插件会自动监听 Vault 内笔记的创建、更新与删除，并通过 WebSocket 实时同步。</li></ol><h3 id="_3-手动全量同步" tabindex="-1">3. 手动全量同步 <a class="header-anchor" href="#_3-手动全量同步" aria-label="Permalink to &quot;3. 手动全量同步&quot;">​</a></h3><p>若需主动拉取远端全部笔记：</p><ol><li>打开插件设置页。</li><li>点击 <strong>「手动同步」</strong>（Manual Sync）。</li><li>在同步日志中查看进度，等待「同步完成」提示。</li></ol><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><ul><li><strong>笔记实时同步</strong>：自动同步 Vault 内所有 <code>.md</code> 的增删改</li><li><strong>配置同步</strong>：多端 Obsidian 配置可同步，无需手动拷贝配置文件（需插件 v1.4+、服务端 v1.0+）</li><li><strong>离线删除补全</strong>：离线期间的删除/变更，下次连接时与服务端对齐</li><li><strong>附件云预览</strong>：附件可在线预览，减少本地占用</li><li><strong>同步日志</strong>：便于排查每次同步的详细情况</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://github.com/haierkeys/obsidian-fast-note-sync" target="_blank" rel="noreferrer">obsidian-fast-note-sync（插件）</a></li><li><a href="https://github.com/haierkeys/fast-note-sync-service" target="_blank" rel="noreferrer">fast-note-sync-service（服务端）</a></li><li><a href="https://github.com/haierkeys/obsidian-fast-note-sync/blob/master/docs/README.zh-TW.md" target="_blank" rel="noreferrer">插件中文说明</a></li></ul>',24)])])}const f=t(s,[["render",n]]);export{g as __pageData,f as default};
